{"formatVersion":3,"title":"Reading log","description":"Track books and pages, with a running total of pages and a count of books logged.","capabilities":[],"capabilityResults":false,"stateSchema":{"entries":{"type":"list","maxItems":100,"fields":{"id":"string","name":"string","pages":"number"}},"draftName":"string","draftPages":"number","editingId":"string","nextId":"number","message":"string","total":"number","books":"number"},"initialState":{"entries":[],"draftName":"","draftPages":0,"editingId":"","nextId":0,"message":"Enter a book name and its page count, then tap Add.","total":0,"books":0},"behaviorBindings":{"bookName":"editName","bookPages":"editPages","add":"add","records":[3],"total":[1]},"ui":{"type":"column","children":[{"type":"section","text":"Add a book","children":[{"type":"input","text":"Book name","bind":"draftName","action":"editName","maxLength":200,"keyboard":"text","imeAction":"next"},{"type":"numberInput","text":"Pages","bind":"draftPages","action":"editPages","min":0,"max":1000000},{"type":"button","text":"Add","action":"add","variant":"filled"},{"type":"text","text":"Status","bind":"message"}]},{"type":"metric","text":"Total pages","bind":"total","format":"number","style":{"emphasis":"number"}},{"type":"metric","text":"Books logged","bind":"books","format":"number","style":{"emphasis":"number"}},{"type":"list","text":"Reading log","bind":"entries","columns":[{"text":"Book","field":"name"},{"text":"Pages","field":"pages"}],"emptyText":"No books yet. Add your first book above.","rowActions":[{"action":"editEntry","text":"Edit"},{"action":"remove","text":"Remove"}]}]},"source":"const st = input.state;
const ev = input.event;

if (!ev || ev.type !== 'action') {
  return {state: st};
}

const MAX_PAGES = 1000000;
const BIG = 9007199254740991;

const clampPages = function (v) {
  let n = typeof v === 'number' ? v : Number(v);
  if (!isFinite(n) || n < 0) n = 0;
  if (n > MAX_PAGES) n = MAX_PAGES;
  return Math.round(n);
};

const copyList = function (list) {
  const out = [];
  const src = Array.isArray(list) ? list : [];
  for (let i = 0; i < src.length && i < 100; i++) {
    const r = src[i];
    if (!r || typeof r.id !== 'string' || r.id === '') continue;
    out.push({
      id: r.id,
      name: typeof r.name === 'string' ? r.name : '',
      pages: typeof r.pages === 'number' && isFinite(r.pages) && r.pages >= 0 ? r.pages : 0
    });
  }
  return out;
};

const next = {
  entries: copyList(st.entries),
  draftName: typeof st.draftName === 'string' ? st.draftName : '',
  draftPages: clampPages(st.draftPages),
  editingId: typeof st.editingId === 'string' ? st.editingId : '',
  nextId: typeof st.nextId === 'number' && isFinite(st.nextId) ? st.nextId : 0,
  message: typeof st.message === 'string' ? st.message : '',
  total: typeof st.total === 'number' && isFinite(st.total) ? st.total : 0,
  books: typeof st.books === 'number' && isFinite(st.books) ? st.books : 0
};

const recalc = function () {
  let t = 0;
  for (let i = 0; i < next.entries.length; i++) t += next.entries[i].pages;
  if (isFinite(t) && Math.abs(t) <= BIG) {
    next.total = t;
    next.books = next.entries.length;
  }
};

const act = ev.actionId;
const val = ev.value;

if (act === 'editName') {
  next.draftName = typeof val === 'string' ? val.slice(0, 200) : '';
} else if (act === 'editPages') {
  next.draftPages = clampPages(val);
} else if (act === 'add') {
  const name = String(next.draftName).trim().slice(0, 200);
  const pages = clampPages(next.draftPages);
  if (name === '') {
    next.message = 'Enter a book name before adding it.';
  } else {
    let idx = -1;
    if (next.editingId !== '') {
      for (let i = 0; i < next.entries.length; i++) {
        if (next.entries[i].id === next.editingId) { idx = i; break; }
      }
    }
    if (idx >= 0) {
      next.entries[idx] = {id: next.entries[idx].id, name: name, pages: pages};
      next.message = 'Updated \u0022' + name + '\u0022.';
    } else if (next.entries.length >= 100) {
      next.message = 'The log is full. Remove a book before adding another.';
    } else {
      next.entries.push({id: String(next.nextId), name: name, pages: pages});
      next.nextId = next.nextId + 1;
      next.message = 'Added \u0022' + name + '\u0022.';
    }
    next.draftName = '';
    next.draftPages = 0;
    next.editingId = '';
    recalc();
  }
} else if (act === 'editEntry') {
  const key = typeof val === 'string' ? val : '';
  let found = null;
  for (let i = 0; i < next.entries.length; i++) {
    if (next.entries[i].id === key) { found = next.entries[i]; break; }
  }
  if (found) {
    next.draftName = found.name;
    next.draftPages = found.pages;
    next.editingId = found.id;
    next.message = 'Editing \u0022' + found.name + '\u0022. Change the fields, then tap Add to save.';
  } else {
    next.message = 'That book is no longer in the log.';
  }
} else if (act === 'remove') {
  const key = typeof val === 'string' ? val : String(val);
  let idx = -1;
  for (let i = 0; i < next.entries.length; i++) {
    if (next.entries[i].id === key) { idx = i; break; }
  }
  if (idx < 0) {
    const n = Number(key);
    if (isFinite(n) && Math.floor(n) === n && n >= 0 && n < next.entries.length) idx = n;
  }
  if (idx < 0) {
    next.message = 'That book is no longer in the log.';
  } else {
    const gone = next.entries[idx];
    next.entries.splice(idx, 1);
    if (next.editingId === gone.id) {
      next.editingId = '';
      next.draftName = '';
      next.draftPages = 0;
    }
    next.message = 'Removed \u0022' + gone.name + '\u0022.';
    recalc();
  }
}

return {state: next};"}
